// Licznik i napięcie z potencjometru na wyświetlaczu LCD z konwerterem I²C (adres 0x27).
#include <LiquidCrystal_I2C.h>

LiquidCrystal_I2C lcd(0x27, 16, 2);

void setup() {
  lcd.init();
  lcd.backlight();
  lcd.print("Czesc!");
  Serial.begin(9600);
}

void loop() {
  static unsigned long start = millis();
  float u = analogRead(A0) * 5.0 / 1023;
  lcd.setCursor(0, 1);
  lcd.print("A0=");
  lcd.print(u, 2);
  lcd.print("V t=");
  lcd.print((millis() - start) / 1000);
  lcd.print("s  ");
  Serial.println(u);
  delay(200);
}
